Definition CASC_STACK : Z := 80 + RB2_STACK.
Definition RK_casc : Z := 1 + RK_pix + RK_pix.
Definition RB_casc (w h : Z) : Z :=
  2 ^ 17 + RB_pixT (4 * (wpl_of (w / 2) 1 * (h / 2))) + RB_pixT (4 * (wpl_of (w / 2 / 2) 1 * (h / 2 / 2))).
Definition CSC (s : Z) (ret : word) (regs : bvmap 5 word) : list (Z * word) :=
  [(s - 8, ret); (s - 16, getr regs 8); (s - 24, getr regs 9); (s - 32, getr regs 18); (s - 40, getr regs 19); (s - 48, getr regs 20);
   (s - 56, getr regs 21)]%Z.

Ltac rzm HW RUN := eapply rz_msteps; [exact (mp_halted _ (w_pure _ _ _ _ HW)) | exact (mp_lazy _ (w_pure _ _ _ _ HW)) | exact RUN |].
Ltac fa9 := repeat (apply Forall_cons; [cbn [fst]; lia |]); apply Forall_nil.
Ltac erest := let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx; cbn [In] in Hx; repeat (destruct Hx as [<-|Hx]; [csr; reflexivity |]); destruct Hx.

