(* [comment removed for export] *)
Section Tab.
Variables (C : lctx) (Ar A : AS) (md : Model) (mB : word -> option byte) (s tab : Z) (S : TSet).
Hypothesis CK : Cok C.
Hypothesis SUB : sub_live Ar A.
Hypothesis Lt : live A (Z_to_bv 64 tab) = Some 256%Z.
Hypothesis Ltr : live Ar (Z_to_bv 64 tab) = None.
Hypothesis Lt0 : live (c_A0 C) (Z_to_bv 64 tab) = None.
Hypothesis Htab : (0 <= tab < 2 ^ 64)%Z.

Definition FTt (m : word -> option byte) : Prop := forall a : word, ~ (tab <= u a < tab + 256)%Z -> m a = mB a.

Lemma cs_tab_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (k : Z),
  W C A m md -> POSTM C Ar s mB m -> FTt m -> (0 <= k)%Z -> (Z.of_nat n = 255 - k)%Z ->
  regs_agree (fun x => In x [5; 6; 7; 10; 11; 12; 13; 15; 16; 17; 28; 29]%list) r0 r ->
  getr r 15 = Z_to_bv 64 (tab + k) -> getr r 14 = Z_to_bv 64 (tab + 256) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTt m' ->
     regs_agree (fun x => In x [5; 6; 7; 10; 11; 12; 13; 15; 16; 17; 28; 29]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x93f34 : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x93ed8 : word) m al_rom) md) S.
